1	#include "core/push_plan.h"
2	
3	typedef struct {
4	  int first_y, last_y, x0, x1;
5	  int64_t rows, pixels;
6	} Group;
7	
8	static int64_t group_cost(const Group *g) {
9	  int64_t h = g->last_y - g->first_y + 1, w = g->x1 - g->x0 + 1;
10	  return PUSH_FLUSH_NS + h * PUSH_FLUSH_ROW_NS + w * h * PUSH_FLUSH_PIXEL_NS +
11	         g->rows * PUSH_CALL_NS + g->pixels * PUSH_COPY_PIXEL_NS;
12	}
13	
14	static Group merge(const Group *a, const Group *b) {
15	  Group g = *a;
16	  g.last_y = b->last_y;
17	  if (b->x0 < g.x0) g.x0 = b->x0;
18	  if (b->x1 > g.x1) g.x1 = b->x1;
19	  g.rows += b->rows;
20	  g.pixels += b->pixels;
21	  return g;
22	}
23	
24	PushKind push_plan(Canvas *c, PushRow *rows, int *count, bool use_disc) {
25	  int n = 0;
26	  int64_t total_ns = 0;
27	  Group cur = {0};
28	  for (int y = 0; y < c->h; y++) {
29	    int x0, x1;
30	    if (!canvas_dirty_row(c, y, &x0, &x1)) continue;
31	    if (use_disc) {
32	      int v0, v1;
33	      if (!canvas_visible_span(c, y, &v0, &v1)) continue;
34	      if (x0 < v0) x0 = v0;
35	      if (x1 > v1) x1 = v1;
36	      if (x0 > x1) continue;
37	    }
38	    Group one = {y, y, x0, x1, 1, x1 - x0 + 1};
39	    if (n == 0) {
40	      cur = one;
41	    } else {
42	      Group merged = merge(&cur, &one);
43	      if (group_cost(&merged) <= group_cost(&cur) + group_cost(&one)) {
44	        cur = merged;
45	      } else {
46	        rows[n - 1].end_of_group = true;
47	        total_ns += group_cost(&cur);
48	        cur = one;
49	      }
50	    }
51	    rows[n++] = (PushRow){y, x0, x1, false};
52	  }
53	  canvas_clear_dirty(c);
54	  *count = 0;
55	  if (n == 0) return PUSH_NONE;
56	  rows[n - 1].end_of_group = true;
57	  total_ns += group_cost(&cur);
58	  if (total_ns >= (int64_t)c->w * c->h * PUSH_PIXEL_NS) return PUSH_ALL;
59	  *count = n;
60	  return PUSH_ROWS;
61	}
62	
63	int push_present(Canvas *c, PushRow *scratch, const PushSink *sink, bool use_disc) {
64	  int count;
65	  switch (push_plan(c, scratch, &count, use_disc)) {
66	    case PUSH_NONE:
67	      return 0;
68	    case PUSH_ALL:
69	      sink->all(sink->ctx);
70	      return c->h;
71	    default:
72	      for (int i = 0; i < count; i++) {
73	        if (i == 0 || scratch[i - 1].end_of_group) sink->begin(sink->ctx);
74	        sink->row(sink->ctx, scratch[i].y, scratch[i].x0, scratch[i].x1);
75	        if (scratch[i].end_of_group) sink->end(sink->ctx);
76	      }
77	      return count;
78	  }
79	}
